query OrderScreen($id: ID!) {
  order(id: $id) {
    status
    eta
    rider { name phone }
    items { name qty }
  }
}

type Order {
  id: ID!
  status: OrderStatus!
  eta: DateTime
  restaurant: Restaurant!
  rider: Rider
  items: [OrderItem!]!
}

type Restaurant {
  id: ID!
  name: String!
  menu: [Dish!]!
}

type Query {
  order(id: ID!): Order
  restaurants(near: String!, first: Int, after: String): RestaurantPage!
}
